var ctx = context.Background()

func at(n int) string { return fmt.Sprintf("2026-11-03T12:00:%02d.000000000Z", n) }

// install copies a fixture generated by 6172744 into a fresh directory, pointing
// its absolute attachment paths at that directory as 0.1.0 wrote them.
func install(t *testing.T, name string) string {
	t.Helper()
	dir := filepath.Join(t.TempDir(), "data")
	if err := os.MkdirAll(dir, 0o700); err != nil {
		t.Fatal(err)
	}
	// 0.1.0 resolves its data directory before writing absolute snapshot paths.
	dir, err := filepath.EvalSymlinks(dir)
	if err != nil {
		t.Fatal(err)
	}
	root := filepath.Join("testdata", "fixtures", name, "data")
	err = filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
		if err != nil || d.IsDir() {
			return err
		}
		rel, _ := filepath.Rel(root, path)
		data, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		data = bytes.ReplaceAll(data, []byte("@DATADIR@"), []byte(dir))
		target := filepath.Join(dir, rel)
		if err = os.MkdirAll(filepath.Dir(target), 0o700); err != nil {
			return err
		}
		return os.WriteFile(target, data, 0o600)
	})
	if err != nil && !os.IsNotExist(err) {
		t.Fatal(err)
	}
	return dir
}

func writeJournal(t *testing.T, dir string, lines ...string) {
	t.Helper()
	if err := os.WriteFile(filepath.Join(dir, journalName), []byte(strings.Join(lines, "")), 0o600); err != nil {
		t.Fatal(err)
	}
}

func line(session, state, request string) string {
	r := fmt.Sprintf(`{"at":"2026-11-03T10:00:00Z","sessionId":%q,"provider":"codex","providerId":"prov-%s","cwd":"/work","state":%q`, session, session, state)
	if request != "" {
		r += fmt.Sprintf(`,"requestId":%q`, request)
	}
	return r + "}\n"
}

// snapshot is every file's bytes and mode under dir, except console.lock and,
// when withLog is false, the event log's own files.
func snapshot(t *testing.T, dir string, withLog bool) map[string]string {
	t.Helper()
	out := map[string]string{}
	err := filepath.WalkDir(dir, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		rel, _ := filepath.Rel(dir, path)
		name := d.Name()
		if name == eventlog.LockName || !withLog && strings.HasPrefix(name, "facts.db") {
			return nil
		}
		info, err := d.Info()
		if err != nil {
			return err
		}
		if d.IsDir() {
			out[rel] = "dir"
			return nil
		}
		data, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		out[rel] = fmt.Sprintf("%v %d %s %d", info.Mode(), info.Size(), sha(data), info.ModTime().UnixNano())
		return nil
	})
	if err != nil {
		t.Fatal(err)
	}
	return out
}

func sameFiles(t *testing.T, before, after map[string]string) {
	t.Helper()
	for name, v := range before {
		if after[name] != v {
			t.Fatalf("%s changed: %q -> %q", name, v, after[name])
		}
	}
	for name := range after {
		if _, ok := before[name]; !ok {
			t.Fatalf("%s appeared", name)
		}
	}
}

func observed(t *testing.T, name string) string {
	data, err := os.ReadFile(filepath.Join("testdata", "fixtures", name, "observed-0.1.txt"))
	if err != nil {
		t.Fatal(err)
	}
	return string(data)
}

// The decoder agrees with 6172744's own restore() on every fixture: the same
// sessions, in the same order, once 0.1.0's window of 24 is applied, and the same
// refusals, except that a torn tail is set aside instead of refusing.
func TestDecoderMatchesObservedRestore(t *testing.T) {
	entries, err := os.ReadDir(filepath.Join("testdata", "fixtures"))
	if err != nil || len(entries) < 9 {
		t.Fatalf("fixtures missing: %v %d", err, len(entries))
	}
	for _, e := range entries {
		name := e.Name()
		t.Run(name, func(t *testing.T) {
			dir := install(t, name)
			obs := observed(t, name)
			j, err := readJournal(dir)
			if err != nil {
				t.Fatal(err)
			}
			got, err := DecodeJournal(j.data, j.present)
			switch {
			case strings.HasPrefix(obs, "refuses: console journal is incomplete") && name == "torn-tail":
				if err != nil || got.Torn == nil {
					t.Fatalf("torn tail not set aside: %v", err)
				}
				return
			case strings.HasPrefix(obs, "refuses: console journal"):
				if !errors.Is(err, ErrRefused) {
					t.Fatalf("0.1.0 refuses this journal but the decoder accepted it: %v", err)
				}
				return
			case err != nil:
				t.Fatal(err)
			case strings.HasPrefix(obs, "refuses:"):
				return // 0.1.0 refused over its queue files, which K3 reports instead.
			}
			var want []string
			for _, l := range strings.Split(obs, "\n") {
				if strings.HasPrefix(l, "session ") {
					want = append(want, strings.Fields(l)[1])
				}
			}
			var ids []string
			for _, s := range got.Sessions {
				ids = append(ids, s.ID)
			}
			if len(ids) > 24 {
				ids = ids[len(ids)-24:]
			}
			if strings.Join(ids, ",") != strings.Join(want, ",") {
				t.Fatalf("sessions %v, 0.1.0 restored %v", ids, want)
			}
			if strings.Contains(obs, "review ") != (len(got.Reviews) > 0) {
				t.Fatalf("reviews %v disagree with 0.1.0", got.Reviews)
			}
		})
	}
}

func TestJournalEdges(t *testing.T) {
	for name, tc := range map[string]struct {
		data    string
		refused bool
		torn    bool
		count   int
	}{
		"null line skipped":           {line("a", "created", "") + "null\n", false, false, 1},
		"empty line refused":          {line("a", "created", "") + "\n", true, false, 0},
		"unknown state refused":       {line("a", "teleported", ""), true, false, 0},
		"complete final, no newline":  {strings.TrimSuffix(line("a", "created", ""), "\n"), false, false, 1},
		"torn final line":             {line("a", "created", "") + `{"sessionId":"b"`, false, true, 1},
		"closed dropped":              {line("a", "created", "") + line("a", "closed", ""), false, false, 0},
		"no provider id skipped":      {`{"sessionId":"a","state":"admission_failed"}` + "\n", false, false, 0},
		"long line refused":           {`{"sessionId":"a","state":"created","cwd":"` + strings.Repeat("x", maxLineBytes) + `"}` + "\n", true, false, 0},
		"checkpoint state is routing": {line("a", "created", "") + `{"sessionId":"a","providerId":"p","taskId":"t","state":"checkpoint:x"}` + "\n", false, false, 1},
	} {
		t.Run(name, func(t *testing.T) {
			j, err := DecodeJournal([]byte(tc.data), true)
			if errors.Is(err, ErrRefused) != tc.refused || err != nil && !tc.refused {
				t.Fatalf("refused=%v: %v", tc.refused, err)
			}
			if tc.refused {
				return
			}
			if (j.Torn != nil) != tc.torn || len(j.Sessions) != tc.count {
				t.Fatalf("torn=%q sessions=%d", j.Torn, len(j.Sessions))
			}
		})
	}
	big := bytes.Repeat([]byte(line("a", "created", "")), MaxJournalBytes/100)
	if _, err := DecodeJournal(big, true); !errors.Is(err, ErrRefused) {
		t.Fatalf("over 8 MiB accepted: %v", err)
	}
	// The digest covers a complete final record and excludes only a torn tail.
	whole := line("a", "created", "")
	if JournalDigest([]byte(whole+`{"x"`)) != JournalDigest([]byte(whole)) {
		t.Fatal("torn tail changed the digest")
	}
	if JournalDigest([]byte(whole+strings.TrimSuffix(line("b", "created", ""), "\n"))) == JournalDigest([]byte(whole)) {
		t.Fatal("a complete final record is outside the digest")
	}
}

// Each mapping row of the plan, through a real import.
func TestMappingRows(t *testing.T) {
	dir := filepath.Join(t.TempDir(), "data")
	if err := os.MkdirAll(dir, 0o700); err != nil {
		t.Fatal(err)
	}
	writeJournal(t, dir,
		line("none", "created", ""),
		line("cwd", "created", ""), line("cwd", "intent", "r"), line("cwd", "final", "r"), line("cwd", "cwd", ""),
		line("intent", "intent", "r"), line("accepted", "accepted", "r"), line("unknown", "unknown", "r"),
		line("final", "final", "r"), line("rejected", "rejected", "r"), line("paused", "paused", "r"),
		line("gone", "created", ""), line("gone", "closed", ""),
		`{"sessionId":"task","provider":"claude","providerId":"c","cwd":"/w","state":"created","taskId":"t1","checkpoint":{"id":"t1","generation":2,"inputRevision":3,"objectiveHash":"abc","passes":{"plan":"d"}}}`+"\n")
	log, p, outcome, err := Import(ctx, dir, Options{Now: at(1)})
	if err != nil || outcome != Imported {
		t.Fatalf("%s %v", outcome, err)
	}
	defer log.Close()
	want := map[string]kernel.Receipt{"none": kernel.ReceiptNone, "cwd": kernel.ReceiptFinal, "intent": kernel.ReceiptUnknown, "accepted": kernel.ReceiptUnknown,
		"unknown": kernel.ReceiptUnknown, "final": kernel.ReceiptFinal, "rejected": kernel.ReceiptRejected, "paused": kernel.ReceiptRejected, "task": kernel.ReceiptNone}
	if len(p.Sessions) != len(want) {
		t.Fatalf("imported %d sessions, want %d", len(p.Sessions), len(want))
	}
	for id, receipt := range want {
		s := p.Sessions[id]
		if s == nil || !s.ReadOnly || s.Requests[s.LastRequest] != receipt || receipt == kernel.ReceiptNone && s.LastRequest != "" {
			t.Fatalf("%s: %+v, want receipt %q", id, s, receipt)
		}
	}
	if p.Sessions["cwd"].CWD != "/work" || p.LegacyGeneration != 1 || p.LastKind != kernel.FactProcessRestarted {
		t.Fatalf("projection: %+v", p)
	}
}

// Every refusal before commit leaves every file as it was.
func TestRefusalsChangeNothing(t *testing.T) {
	cases := map[string]func(t *testing.T) string{
		"corrupt line":            func(t *testing.T) string { return install(t, "corrupt-line") },
		"review record needs K1d": func(t *testing.T) string { return install(t, "receipts") },
		"queue needs K1c":         func(t *testing.T) string { return install(t, "queue") },
		"orphan queue needs K1c":  func(t *testing.T) string { return install(t, "orphan-queue") },
		"corrupt queue needs K1c": func(t *testing.T) string { return install(t, "corrupt-queue") },
		"more than MaxOpenSessions": func(t *testing.T) string {
			dir := filepath.Join(t.TempDir(), "data")
			os.MkdirAll(dir, 0o700)
			var lines []string
			for i := 0; i <= kernel.MaxOpenSessions; i++ {
				lines = append(lines, line(fmt.Sprintf("s%04d", i), "created", ""))
			}
			writeJournal(t, dir, lines...)
			return dir
		},
		"identity out of shape": func(t *testing.T) string {
			dir := filepath.Join(t.TempDir(), "data")
			os.MkdirAll(dir, 0o700)
			writeJournal(t, dir, line("bad id", "created", ""))
			return dir
		},
	}
	for name, setup := range cases {
		t.Run(name, func(t *testing.T) {
			dir := setup(t)
			before := snapshot(t, dir, true)
			if _, err := Verify(dir); err == nil && !strings.Contains(name, "needs") && name != "more than MaxOpenSessions" && name != "identity out of shape" {
				t.Fatal("verify accepted")
			}
			_, _, _, err := Import(ctx, dir, Options{Now: at(1)})
			if !errors.Is(err, ErrRefused) {
				t.Fatalf("not refused: %v", err)
			}
			sameFiles(t, before, snapshot(t, dir, true))
		})
	}
	// A held lock refuses before reading.
	dir := install(t, "many")
	before := snapshot(t, dir, true)
	lock, err := eventlog.LockDir(dir)
	if err != nil {
		t.Fatal(err)
	}
	if _, _, _, err = Import(ctx, dir, Options{Now: at(1)}); !errors.Is(err, eventlog.ErrLocked) {
		t.Fatalf("import ran under a held lock: %v", err)
	}
	lock.Release()
	sameFiles(t, before, snapshot(t, dir, true))
}

// The guard lists what is missing.
func TestVerifyReportsGuard(t *testing.T) {
	r, err := Verify(install(t, "queue-no-identity"))
	if err != nil || len(r.Unsupported) != 1 || len(r.Queue.Sessions) != 1 {
		t.Fatalf("%+v %v", r, err)
	}
	q := r.Queue.Sessions[0]
	if q.Unknown != "" || len(q.Inputs) != 1 || !q.Inputs[0].NoIdentity || q.Inputs[0].Status != "held" || !q.Inputs[0].Snapshots[0].Intact {
		t.Fatalf("queue: %+v", q)
	}
	r, err = Verify(install(t, "corrupt-queue"))
	if err != nil || r.Queue.Sessions[0].Unknown != "queue_unreadable" {
		t.Fatalf("corrupt queue: %+v %v", r.Queue, err)
	}
	r, err = Verify(install(t, "orphan-queue"))
	if err != nil || len(r.Queue.Orphans) != 1 || len(r.Unsupported) != 1 {
		t.Fatalf("orphan: %+v %v", r.Queue, err)
	}
}

// recorder logs the order of filesystem calls and can fail one of them.
type recorder struct {
	calls  []string
	failAt int
}

func (r *recorder) note(op, path string) error {
	r.calls = append(r.calls, op+" "+filepath.Base(path))
	if r.failAt > 0 && len(r.calls) == r.failAt {
		return errors.New("injected failure")
	}
	return nil
}

func (r *recorder) WriteSync(path string, data []byte, exclusive bool) error {
	if err := r.note("write+fsync", path); err != nil {
		return err
	}
	return osOps{}.WriteSync(path, data, exclusive)
}
func (r *recorder) Link(a, b string) error {
	if err := r.note("link", b); err != nil {
		return err
	}
	return os.Link(a, b)
}
func (r *recorder) Rename(a, b string) error {
	if err := r.note("rename", a); err != nil {
		return err
	}
	return os.Rename(a, b)
}
func (r *recorder) SyncDir(dir string) error {
	if err := r.note("fsync-dir", ""); err != nil {
		return err
	}
	return osOps{}.SyncDir(dir)
}

func TestSwapOrder(t *testing.T) {
	dir := install(t, "torn-tail")
	rec := &recorder{}
	log, _, outcome, err := Import(ctx, dir, Options{Now: at(1), fs: rec})
	if err != nil || outcome != Imported {
		t.Fatalf("%s %v", outcome, err)
	}
	log.Close()
	ts := stamp(at(1))
	probe := []string{"write+fsync .import-probe", "link .import-probe.link", "write+fsync .import-probe.next", "rename .import-probe.next"}
	want := append(append(append([]string{}, probe...), probe...),
		"write+fsync sessions.jsonl.torn-"+ts, "fsync-dir .",
		"link sessions.jsonl.imported-"+ts, "fsync-dir .",
		"write+fsync sessions.jsonl.sentinel-tmp", "rename sessions.jsonl.sentinel-tmp", "fsync-dir .")
	if strings.Join(rec.calls, "\n") != strings.Join(want, "\n") {
		t.Fatalf("order:\n%s\nwant:\n%s", strings.Join(rec.calls, "\n"), strings.Join(want, "\n"))
	}
	data, _ := os.ReadFile(filepath.Join(dir, journalName))
	if string(data) != Sentinel {
		t.Fatal("sentinel not installed")
	}
	if names, _ := filepath.Glob(filepath.Join(dir, ".import-probe*")); len(names) != 0 {
		t.Fatalf("probe left behind: %v", names)
	}
}

// A failure at every filesystem step, then a normal open, always ends imported,
// swapped and with the journal kept, or not imported with nothing lost.
func TestFailureAtEachStepRecovers(t *testing.T) {
	for _, fixture := range []string{"torn-tail", "many", "missing-journal"} {
		dir := install(t, fixture)
		rec := &recorder{}
		if log, _, _, err := Import(ctx, dir, Options{Now: at(1), fs: rec}); err == nil {
			log.Close()
		} else {
			t.Fatal(err)
		}
		steps := len(rec.calls)
		for step := 1; step <= steps; step++ {
			t.Run(fmt.Sprintf("%s/%d", fixture, step), func(t *testing.T) {
				dir := install(t, fixture)
				original, _ := os.ReadFile(filepath.Join(dir, journalName))
				_, _, _, err := Import(ctx, dir, Options{Now: at(1), fs: &recorder{failAt: step}})
				if err == nil {
					t.Fatal("injected failure not reported")
				}
				log, p, outcome, err := Import(ctx, dir, Options{Now: at(2)})
				if err != nil {
					t.Fatalf("recovery: %v", err)
				}
				defer log.Close()
				if p.LegacyGeneration != 1 || p.LegacyImported != JournalDigest(original) {
					t.Fatalf("after %s: %+v", outcome, p)
				}
				data, _ := os.ReadFile(filepath.Join(dir, journalName))
				if string(data) != Sentinel {
					t.Fatalf("no sentinel after %s", outcome)
				}
				if len(original) > 0 {
					if name, _ := findImported(dir, p.LegacyImported); name == "" {
						t.Fatal("journal copy lost")
					}
				}
			})
		}
	}
}

func TestRecoveryRows(t *testing.T) {
	dir := install(t, "many")
	log, _, _, err := Import(ctx, dir, Options{Now: at(1)})
	if err != nil {
		t.Fatal(err)
	}
	log.Close()
	log, _, outcome, err := Import(ctx, dir, Options{Now: at(2)})
	if err != nil || outcome != AlreadyImported {
		t.Fatalf("%s %v", outcome, err)
	}
	log.Close()
	os.Remove(filepath.Join(dir, journalName))
	log, _, outcome, err = Import(ctx, dir, Options{Now: at(3)})
	if err != nil || outcome != SentinelReinstalled {
		t.Fatalf("%s %v", outcome, err)
	}
	log.Close()
	// A sentinel with no log is refused, never imported as empty.
	lost := filepath.Join(t.TempDir(), "data")
	os.MkdirAll(lost, 0o700)
	writeJournal(t, lost, Sentinel)
	if _, _, _, err = Import(ctx, lost, Options{Now: at(1)}); !errors.Is(err, ErrRefused) {
		t.Fatalf("sentinel without a log: %v", err)
	}
}

func TestRollbackRoundTrips(t *testing.T) {
	dir := install(t, "torn-tail")
	original, _ := os.ReadFile(filepath.Join(dir, journalName))
	kept, _ := Acknowledged(original)
	log, _, _, err := Import(ctx, dir, Options{Now: at(1)})
	if err != nil {
		t.Fatal(err)
	}
	log.Close()
	if err = Rollback(ctx, dir, at(2)); err != nil {
		t.Fatal(err)
	}
	restored, _ := os.ReadFile(filepath.Join(dir, journalName))
	if !bytes.Equal(restored, kept) {
		t.Fatal("rollback did not restore the acknowledged journal")
	}
	if _, err := DecodeJournal(restored, true); err != nil {
		t.Fatalf("restored journal is not one 0.1.0 reads: %v", err)
	}
	// A second rollback sees 0.1.0's journal, not the sentinel, and refuses.
	if err = Rollback(ctx, dir, at(3)); !errors.Is(err, ErrRefused) {
		t.Fatalf("second rollback: %v", err)
	}
	if after, _ := os.ReadFile(filepath.Join(dir, journalName)); !bytes.Equal(after, kept) {
		t.Fatal("second rollback changed the journal")
	}
	// Nothing changed in 0.1.0: the upgrade finishes the swap.
	log, p, outcome, err := Import(ctx, dir, Options{Now: at(4)})
	if err != nil || outcome != SwapFinished || p.LegacyGeneration != 1 {
		t.Fatalf("%s %v", outcome, err)
	}
	log.Close()
	// 0.1.0 wrote to the journal: refuse and name --reimport, then reimport.
	if err = Rollback(ctx, dir, at(5)); err != nil {
		t.Fatal(err)
	}
	f, _ := os.OpenFile(filepath.Join(dir, journalName), os.O_APPEND|os.O_WRONLY, 0o600)
	f.WriteString(line("after", "created", ""))
	f.Close()
	before := snapshot(t, dir, false)
	if _, _, _, err = Import(ctx, dir, Options{Now: at(6)}); !errors.Is(err, ErrRefused) || !strings.Contains(err.Error(), "--reimport") {
		t.Fatalf("changed journal: %v", err)
	}
	sameFiles(t, before, snapshot(t, dir, false))
	log, p, outcome, err = Import(ctx, dir, Options{Now: at(7), Reimport: true})
	if err != nil || outcome != Imported || p.LegacyGeneration != 2 {
		t.Fatalf("reimport: %s %v", outcome, err)
	}
	defer log.Close()
	if p.Sessions["after:g2"] == nil || p.Sessions["after"] != nil || p.Sessions["created:g2"] == nil || p.Sessions["created"] == nil {
		t.Fatal("reimport did not add generation 2 beside generation 1")
	}
	log.Close()
	// Two .imported copies now exist. Rollback picks generation 2's by its digest.
	if names, _ := filepath.Glob(filepath.Join(dir, journalName+".imported-*")); len(names) != 2 {
		t.Fatalf("imported copies: %v", names)
	}
	if err = Rollback(ctx, dir, at(8)); err != nil {
		t.Fatal(err)
	}
	if restored, _ := os.ReadFile(filepath.Join(dir, journalName)); !bytes.Contains(restored, []byte(`"sessionId":"after"`)) {
		t.Fatal("rollback restored an older generation's journal")
	}
}

// R1: after a rollback, 0.1.0 can queue an input without touching the journal.
func TestChangedQueueAfterRollbackRefuses(t *testing.T) {
	dir := install(t, "many")
	log, _, _, err := Import(ctx, dir, Options{Now: at(1)})
	if err != nil {
		t.Fatal(err)
	}
	log.Close()
	if err = Rollback(ctx, dir, at(2)); err != nil {
		t.Fatal(err)
	}
	os.MkdirAll(filepath.Join(dir, queueDirName), 0o700)
	sum := sha256.Sum256([]byte("m29"))
	os.WriteFile(filepath.Join(dir, queueDirName, hex.EncodeToString(sum[:])+".json"), []byte(`{"schema":1}`), 0o600)
	before := snapshot(t, dir, false)
	_, _, _, err = Import(ctx, dir, Options{Now: at(3)})
	if !errors.Is(err, ErrRefused) || !strings.Contains(err.Error(), "queue files changed") {
		t.Fatalf("changed queue: %v", err)
	}
	sameFiles(t, before, snapshot(t, dir, false))
}

func TestMissingJournalImportsEmpty(t *testing.T) {
	dir := install(t, "missing-journal")
	log, p, outcome, err := Import(ctx, dir, Options{Now: at(1)})
	if err != nil || outcome != Imported || len(p.Sessions) != 0 || p.LegacyImported != JournalDigest(nil) {
		t.Fatalf("%s %v %+v", outcome, err, p)
	}
	log.Close()
	if data, _ := os.ReadFile(filepath.Join(dir, journalName)); string(data) != Sentinel {
		t.Fatal("no sentinel, so 0.1.0 could recreate an empty journal")
	}
	if err = Rollback(ctx, dir, at(2)); err != nil {
		t.Fatal(err)
	}
	if data, err := os.ReadFile(filepath.Join(dir, journalName)); err != nil || len(data) != 0 {
		t.Fatalf("rollback of an empty import: %q %v", data, err)
	}
}

// Text, objective and attachment bytes never reach a fact (INV6).
func TestCanaryNeverReachesTheLog(t *testing.T) {
	const canary = "CANARY-7f3a9c"
	dir := filepath.Join(t.TempDir(), "data")
	os.MkdirAll(dir, 0o700)
	writeJournal(t, dir, `{"sessionId":"a","provider":"codex","providerId":"p","cwd":"/w","state":"created","title":"`+canary+`","cascade":{"note":"`+canary+`"}}`+"\n")
	log, _, _, err := Import(ctx, dir, Options{Now: at(1)})
	if err != nil {
		t.Fatal(err)
	}
	log.Close()
	var hits []string
	filepath.WalkDir(dir, func(path string, d fs.DirEntry, err error) error {
		if err == nil && !d.IsDir() && strings.HasPrefix(d.Name(), "facts.db") {
			if data, _ := os.ReadFile(path); bytes.Contains(data, []byte(canary)) {
				hits = append(hits, d.Name())
			}
		}
		return nil
	})
	sort.Strings(hits)
	if len(hits) > 0 {
		t.Fatalf("canary in %v", hits)
	}
	// Queue text stays out of the report too.
	r, err := Verify(install(t, "queue"))
	if err != nil || strings.Contains(fmt.Sprintf("%+v", r), "synthetic queued text") {
		t.Fatalf("queue text in the report: %v", err)
	}
}

// A directory without hard links (FAT, exFAT) refuses before anything is written,
// including the event log.
func TestPreflightRefusesFirst(t *testing.T) {
	dir := install(t, "many")
	before := snapshot(t, dir, true)
	_, _, _, err := Import(ctx, dir, Options{Now: at(1), fs: &recorder{failAt: 2}})
	if !errors.Is(err, ErrRefused) || !strings.Contains(err.Error(), "hard links") {
		t.Fatalf("no hard links: %v", err)
	}
	sameFiles(t, before, snapshot(t, dir, true))
}
